  // Validate args
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('arguments must be an object');
  }
  const { user_id, note } = args;
  if (typeof user_id !== 'string') {
    throw new Error('user_id must be a string');
  }
  // note may be string or null; omitted means null
  if (!('note' in args)) {
    // omitted -> null
  } else if (note !== null && typeof note !== 'string') {
    throw new Error('note must be a string or null');
  }
  // Reject extra fields
  const allowed = new Set(['user_id', 'note']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error('Unknown field: ' + key);
    }
  }
  const resultNote = args.note === undefined ? null : note;
  return {
    content: [{ type: 'text', text: JSON.stringify({ user_id, note: resultNote }) }]
  };
}
